import { MOVEMENTS } from './movements';
import { industryOf } from './industries';
import type { Movement } from './types';

/**
 * Movements worth considering for an industry, strongest first, with the
 * profile's `avoid` list removed. An unknown industry gets every movement:
 * the library narrows a choice, it never blocks one.
 */
export function movementsForIndustry(industryKey: string | null | undefined): Movement[] {
  const profile = industryKey ? industryOf(industryKey) : null;
  if (!profile) return MOVEMENTS;
  const avoid = new Set(profile.avoid);
  const first = profile.fits.map((k) => MOVEMENTS.find((m) => m.key === k)).filter((m): m is Movement => !!m);
  const rest = MOVEMENTS.filter((m) => !avoid.has(m.key) && !profile.fits.includes(m.key));
  return [...first, ...rest];
}
